def make_textbook_entry(content_dict, length="medium", ttype="unit_lesson", tags=None):
    return {
        "subject": content_dict["subject"], "topic": content_dict["topic"], "level": content_dict["level"],
        "length": length, "type": ttype, "title": content_dict["title"],
        "tags": tags or [], "content": content_dict,
        "status": "published", "source": "claude_max_seed_batch26",
    }

textbooks = [
    make_textbook_entry(AMINO_ACID, tags=["アミノ酸", "タンパク質", "α-アミノ酸", "双性イオン", "等電点", "ペプチド結合", "高次構造", "変性"]),
    make_textbook_entry(POLYMER, tags=["高分子化合物", "付加重合", "縮合重合", "ポリエチレン", "ナイロン", "PET", "合成繊維", "合成樹脂"]),
    make_textbook_entry(NEURAL, tags=["神経系", "ニューロン", "活動電位", "シナプス", "Na/K ポンプ", "中枢神経", "末梢神経", "自律神経"]),
    make_textbook_entry(ENDOCRINE, tags=["内分泌系", "ホルモン", "インスリン", "グルカゴン", "甲状腺", "副腎", "フィードバック", "視床下部"]),
    make_textbook_entry(IMMUNE, tags=["免疫", "自然免疫", "獲得免疫", "T細胞", "B細胞", "抗体", "MHC", "ワクチン", "アレルギー"]),
]

with open(OUTPUT, "w", encoding="utf-8") as f:
    json.dump({"textbooks": textbooks}, f, ensure_ascii=False, indent=2)

print(f"✅ 書き出し完了: {OUTPUT}")
print(f"   教材数: {len(textbooks)}")
for t in textbooks:
    print(f"   - {t['subject']} / {t['topic']} ({len(t['content']['sections'])} sections)")
